FROM mk_segment_definition
WHERE tenant_id = #{tenantId}
  AND segment_id = #{segmentId}

SELECT membership_version
FROM mk_audience_member
WHERE tenant_id = #{tenantId}
  AND snapshot_id = #{snapshotId}
  AND subject_hash = #{subjectHash}
FOR UPDATE

mapper.update:
UPDATE mk_audience_member
SET membership_version = #{membershipVersion},
    active_value = #{activeValue},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND snapshot_id = #{snapshotId}
  AND subject_hash = #{subjectHash}

mapper.select:
SELECT
    active_value AS activeValue,
    membership_version AS membershipVersion
FROM mk_audience_member
WHERE tenant_id = #{tenantId}
  AND snapshot_id = #{snapshotId}
  AND subject_hash = #{subjectHash}
